column1:
디자인이랑 테스트벤치 줄게 돌려봐. 디자인: module cnt(input clk, output reg [2:0] q);
always @(posedge clk) q <= q + 1;
endmodule 테벤: module tb; reg clk=0; wire [2:0] q; cnt u(clk,q);
always #5 clk=~clk;
initial #100 $finish;
endmodule

Run this sim for 30 seconds, no waveform. design: module cnt(input clk, output reg [2:0] q);
always @(posedge clk) q <= q + 1;
endmodule tb: module tb; reg clk=0; wire [2:0] q; cnt u(clk,q);
always #5 clk=~clk;
initial #100 $finish;
endmodule

iverilog로 실제로 시뮬 돌려주세요, 커버리지 최소 70%로. 설계 module cnt(input clk, output reg [2:0] q);
always @(posedge clk) q <= q + 1;
endmodule 테스트벤치 module tb; reg clk=0; wire [2:0] q; cnt u(clk,q);
always #5 clk=~clk;
initial #100 $finish;
endmodule

이 assert가 모든 입력에서 성립하는지 증명해줘 depth 30으로 module p(input clk, input a, output reg y);
always @(posedge clk) y <= a;
always @* assert(1);
endmodule

Formally prove the property in this module, bounded only please: module p(input clk, input a, output reg y);
always @(posedge clk) y <= a;
always @* assert(1);
endmodule

형식검증으로 이 속성 참인지 확인 부탁드려요 module p(input clk, input a, output reg y);
always @(posedge clk) y <= a;
always @* assert(1);
endmodule

납품 전에 IP 사인오프 게이트 돌려줘. 커버리지 90% 기준. 디자인 module cnt(input clk, output reg [2:0] q);
always @(posedge clk) q <= q + 1;
endmodule 테벤 module tb; reg clk=0; wire [2:0] q; cnt u(clk,q);
always #5 clk=~clk;
initial #100 $finish;
endmodule

Run the IP sign-off gates with a 50 MHz timing target. design: module cnt(input clk, output reg [2:0] q);
always @(posedge clk) q <= q + 1;
endmodule tb: module tb; reg clk=0; wire [2:0] q; cnt u(clk,q);
always #5 clk=~clk;
initial #100 $finish;
endmodule

사인오프 한번 쫙 돌려주세요 module cnt(input clk, output reg [2:0] q);
always @(posedge clk) q <= q + 1;
endmodule 테스트벤치는 module tb; reg clk=0; wire [2:0] q; cnt u(clk,q);
always #5 clk=~clk;
initial #100 $finish;
endmodule
